82	/// Selects the highest-versioned tag matching `template` out of a full tag
83	/// list previously obtained via [`fetch_all_tags`].
84	fn select_from_tags(
85	    all_tags: &[String],
86	    template: &TagTemplate,
87	    grammar: VersionGrammar,
88	) -> Result<LastTagSelection, GraphError> {
89	    let candidates = matching_tags(all_tags, template)?;
90	    select_last_tag(template, grammar, candidates).map_err(GraphError::from)
91	}
92	
93	/// Like [`select_from_tags`], but reuses a `cache` of already-compiled/
94	/// already-scanned candidates keyed by `template.glob()` -- a
95	/// `[[package-set]]` rule with a fixed (non-`{name}`) `tag-template` string
96	/// applies the identical template to every matching package, so without
97	/// this cache `TagIndex::build`'s per-package loop would recompile the same
98	/// `globset::Glob` and rescan the full tag list once per package sharing
99	/// that template, instead of once per distinct template.
100	fn select_from_tags_cached<'a>(
101	    all_tags: &'a [String],
102	    template: &TagTemplate,
103	    grammar: VersionGrammar,
104	    cache: &mut std::collections::HashMap<String, Vec<&'a str>>,
105	) -> Result<LastTagSelection, GraphError> {
106	    let glob = template.glob();
107	    let candidates = match cache.get(&glob) {
108	        Some(cached) => cached.clone(),
109	        None => {
110	            let matched = matching_tags(all_tags, template)?;
111	            cache.insert(glob, matched.clone());
112	            matched
113	        }
114	    };
115	    select_last_tag(template, grammar, candidates).map_err(GraphError::from)
116	}
