118	/// Resolves the last release tag matching a single package's `template`.
119	///
120	/// Kept for API compatibility with existing callers, and safe to use
121	/// standalone. Note that this re-fetches the full tag list (gix discovery
122	/// or a `CommandRunner` round-trip) on every call; callers resolving tags
123	/// for many packages at once -- notably [`TagIndex::build`] -- fetch the
124	/// list once and reuse it across packages rather than calling this
125	/// function in a loop.
126	pub fn last_tag_for<R: CommandRunner>(
127	    runner: &R,
128	    root: &Path,
129	    template: &TagTemplate,
130	    grammar: VersionGrammar,
131	) -> Result<LastTagSelection, GraphError> {
132	    let git = GitAccess::discover(root, runner);
133	    let all_tags = fetch_all_tags(&git)?;
134	    select_from_tags(&all_tags, template, grammar)
135	}
136	
137	pub struct TagIndex {
138	    last: BTreeMap<PackageId, Option<LastTag>>,
139	    templates: BTreeMap<PackageId, TagTemplate>,
140	    pre_cursor: BTreeMap<PackageId, Option<CommitSha>>,
141	    /// The full, unfiltered raw tag list fetched once during `build` (see
142	    /// `fetch_all_tags`), kept around so callers checking whether a specific
143	    /// tag name already exists (e.g. `create_tags_with_options`, once per
144	    /// release) can consult this in-memory set instead of re-querying `git`
145	    /// once per check.
146	    all_tags: std::collections::BTreeSet<String>,
147	    pub diagnostics: Vec<Diagnostic>,
148	}
149	
150	impl TagIndex {
151	    pub fn build<D: DependencyResolver>(
152	        git: &GitAccess<'_>,
153	        graph: &D,
154	        _cfg: &ResolvedConfig,
155	    ) -> Result<Self, GraphError> {
156	        let mut last = BTreeMap::new();
157	        let mut templates = BTreeMap::new();
158	        let mut pre_cursor = BTreeMap::new();
159	        let diagnostics = Vec::new();
160	
161	        // Fetch the raw tag list exactly once for the whole build, not once
162	        // per package -- see `fetch_all_tags` for why (avoids N gix
163	        // discoveries / N host round-trips for N packages). `git` is shared
164	        // with the caller rather than discovered fresh here, so a single
165	        // `Workspace`-scoped command that also needs git for other reasons
166	        // (e.g. `plan_publish`'s head_sha resolution) doesn't pay for a
167	        // second discovery.
168	        let all_tags = fetch_all_tags(git)?;
169	        let all_tags_set: std::collections::BTreeSet<String> = all_tags.iter().cloned().collect();
170	        let mut glob_cache: std::collections::HashMap<String, Vec<&str>> = std::collections::HashMap::new();
171	
172	        for pkg in graph.packages() {
173	            let default_tmpl = TagTemplate::parse(&format!("{}@{{version}}", pkg.id.display_name()))?;
174	            let tmpl = pkg.tag_template.clone().unwrap_or(default_tmpl);
175	            let sel = select_from_tags_cached(&all_tags, &tmpl, pkg.version_grammar()?, &mut glob_cache)?;
176	            last.insert(pkg.id.clone(), sel.chosen);
177	            templates.insert(pkg.id.clone(), tmpl);
178	            pre_cursor.insert(pkg.id.clone(), None);
179	        }
180	
181	        Ok(TagIndex {
182	            last,
183	            templates,
184	            pre_cursor,
185	            all_tags: all_tags_set,
186	            diagnostics,
187	        })
188	    }
189	
190	    pub fn last_tag(&self, id: &PackageId) -> Option<&LastTag> {
191	        self.last.get(id).and_then(|opt| opt.as_ref())
192	    }
193	
194	    pub fn template(&self, id: &PackageId) -> &TagTemplate {
195	        &self.templates[id]
196	    }
197	
198	    pub fn pre_cursor(&self, id: &PackageId) -> Option<&CommitSha> {
199	        self.pre_cursor.get(id).and_then(|opt| opt.as_ref())
200	    }
201	
202	    /// Returns whether `tag_name` is present in the raw tag list fetched
203	    /// during `build` -- an exact match, not a glob. Lets callers checking
204	    /// tag existence once per release (e.g. `create_tags_with_options`)
205	    /// consult this in-memory set instead of shelling out to `git` again
206	    /// for each one.
207	    pub fn contains_tag(&self, tag_name: &str) -> bool {
208	        self.all_tags.contains(tag_name)
209	    }
210	
211	    /// Constructs an empty `TagIndex` with no packages or tags — useful in
212	    /// unit tests that do not exercise tag-based logic.
213	    pub fn empty() -> Self {
214	        TagIndex {
215	            last: BTreeMap::new(),
216	            templates: BTreeMap::new(),
217	            pre_cursor: BTreeMap::new(),
218	            all_tags: std::collections::BTreeSet::new(),
219	            diagnostics: Vec::new(),
220	        }
221	    }
222	}
